57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        prepareNewOwner(ownerFieldsDto);
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
125	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
126	        if (currentOwner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        currentOwner.setAddress(ownerFieldsDto.getAddress());
130	        currentOwner.setCity(ownerFieldsDto.getCity());
131	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
132	        currentOwner.setLastName(ownerFieldsDto.getLastName());
133	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
134	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
135	        this.clinicService.saveOwner(currentOwner);
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Transactional
141	    @Override
142	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        this.clinicService.deleteOwner(owner);
148	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Pet pet = petMapper.toPet(petFieldsDto);
160	        owner.setId(ownerId);
161	        pet.setOwner(owner);
162	        pet.getType().setName(null);
163	        this.clinicService.savePet(pet);
164	        PetDto petDto = petMapper.toPetDto(pet);
165	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
166	            .buildAndExpand(pet.getId()).toUri());
167	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner != null) {
175	            Pet currentPet = this.clinicService.findPetById(petId);
176	            if (currentPet != null) {
177	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
178	                currentPet.setName(petFieldsDto.getName());
179	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
180	                this.clinicService.savePet(currentPet);
181	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	            }
183	        }
184	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
190	        HttpHeaders headers = new HttpHeaders();
191	        Visit visit = visitMapper.toVisit(visitFieldsDto);
192	        Pet pet = new Pet();
193	        pet.setId(petId);
194	        visit.setPet(pet);
195	        this.clinicService.saveVisit(visit);
196	        VisitDto visitDto = visitMapper.toVisitDto(visit);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
198	            .buildAndExpand(visit.getId()).toUri());
199	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
200	    }
201	
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner != null) {
208	            Pet pet = owner.getPet(petId);
209	            if (pet != null) {
210	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	
216	    /**
217	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
218	     * The required fields are checked, the telephone and email are normalized in place, and
219	     * the resulting telephone is rejected when it already belongs to another owner. Each rule
220	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
221	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
222	     * to be mapped and saved.
223	     *
224	     * @param ownerFieldsDto the submitted owner fields, normalized in place
225	     */
226	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
227	        validateRequiredFields(ownerFieldsDto);
228	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
229	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
230	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
231	        rejectDuplicateHousehold(ownerFieldsDto);
232	    }
233	
234	    /**
235	     * Builds the customer code assigned to a newly created owner. The code is formatted as
236	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
237	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
238	     * one more than the current number of owners. For example the seventh owner named
239	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
240	     *
241	     * @param lastName the owner's last name
242	     * @return the formatted customer code
243	     */
244	    private String nextCustomerCode(String lastName) {
245	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
246	        long sequence = this.clinicService.findAllOwners().size() + 1L;
247	        return String.format("%s-%04d", last3, sequence);
248	    }
249	
250	    /**
251	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
252	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
253	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
254	     * the names of every offending field, which the exception advice renders as a 400 response
255	     * with an {@code errors} array.
256	     *
257	     * @param ownerFieldsDto the submitted owner fields
258	     */
259	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
260	        List<String> missing = new ArrayList<>();
261	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
262	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
263	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
264	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
265	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
266	        if (!missing.isEmpty()) {
267	            throw new RequiredFieldsMissingException(missing);
268	        }
269	    }
270	
271	    private void addIfBlank(List<String> missing, String fieldName, String value) {
272	        if (value == null || value.isBlank()) {
273	            missing.add(fieldName);
274	        }
275	    }
276	
277	    /**
278	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
279	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
280	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
281	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
282	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
283	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
284	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
285	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
286	     *
287	     * @param telephone the submitted telephone value
288	     * @return the normalized E.164 telephone
289	     */
290	    private String normalizeTelephone(String telephone) {
291	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
292	        String e164;
293	        if (cleaned.startsWith("+")) {
294	            e164 = "+" + cleaned.substring(1);
295	        } else {
296	            String national = cleaned;
297	            if (national.startsWith("0")) {
298	                national = national.substring(1);
299	            }
300	            e164 = "+61" + national;
301	        }
302	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
303	            throw new InvalidFieldsException(List.of("telephone"));
304	        }
305	        return e164;
306	    }
307	
308	    /**
309	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
310	     * and a domain containing at least one dot, none of the parts holding whitespace or a
311	     * second {@code @}.
312	     */
313	    private static final java.util.regex.Pattern EMAIL_PATTERN =
314	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
315	
316	    /**
317	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
318	     * accepted and returned unchanged. When present it must be a syntactically valid address;
319	     * the value is stored and returned lower-cased. When present but invalid an
320	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
321	     * response naming the {@code email} field.
322	     *
323	     * @param email the submitted email value, or {@code null} when omitted
324	     * @return the lower-cased email, or {@code null} when none was supplied
325	     */
326	    private String normalizeEmail(String email) {
327	        if (email == null) {
328	            return null;
329	        }
330	        String trimmed = email.trim();
331	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
332	            throw new InvalidFieldsException(List.of("email"));
333	        }
334	        return trimmed.toLowerCase(java.util.Locale.ROOT);
335	    }
336	
337	    /**
338	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
339	     * The telephone is stored in its normalized E.164 form, so a plain equality check
340	     * against every owner's telephone compares E.164 values. When a match is found a
341	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
342	     * 409 Conflict response.
343	     *
344	     * @param telephone the normalized telephone of the owner being created
345	     */
346	    private void rejectDuplicateTelephone(String telephone) {
347	        boolean taken = this.clinicService.findAllOwners().stream()
348	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
349	        if (taken) {
350	            throw new DuplicateTelephoneException(telephone);
351	        }
352	    }
353	
354	    /**
355	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
356	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to
357	     * a single space (and surrounding whitespace trimmed), so for example {@code "Franklin"} at
358	     * {@code "110  W. Liberty St."} clashes with {@code "franklin"} at {@code "110 W. Liberty St."}.
359	     * A request may bypass this rule by setting {@code sharesHousehold} to {@code true}, allowing
360	     * several owners to share one household. When a clash is found and the request did not opt in a
361	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
362	     * Conflict response.
363	     *
364	     * @param ownerFieldsDto the submitted owner fields
365	     */
366	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
367	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
368	            return;
369	        }
370	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
371	        String address = collapseWhitespace(ownerFieldsDto.getAddress());
372	        boolean taken = this.clinicService.findAllOwners().stream()
373	            .anyMatch(existing -> lastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
374	                && address.equalsIgnoreCase(collapseWhitespace(existing.getAddress())));
375	        if (taken) {
376	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
377	        }
378	    }
379	
380	    /**
381	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
382	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
383	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
384	     *
385	     * @param value the value to collapse, or {@code null}
386	     * @return the whitespace-collapsed value, never {@code null}
387	     */
388	    private String collapseWhitespace(String value) {
389	        if (value == null) {
390	            return "";
391	        }
392	        return value.trim().replaceAll("\\s+", " ");
393	    }
394	}
